import{_ as a,o,c as s,a2 as r}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Modpacks : partager une instance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/modpacks.md","filePath":"guide/modpacks.md"}'),n={name:"guide/modpacks.md"};function t(i,e,c,d,l,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="modpacks-partager-une-instance" tabindex="-1">Modpacks : partager une instance <a class="header-anchor" href="#modpacks-partager-une-instance" aria-label="Permalink to &quot;Modpacks : partager une instance&quot;">​</a></h1><p>Un modpack réunit toute une instance (version, loader, mods, réglages) dans un fichier unique : c&#39;est la méthode la plus simple pour que plusieurs joueurs disposent exactement des mêmes mods.</p><h2 id="importer-un-modpack" tabindex="-1">Importer un modpack <a class="header-anchor" href="#importer-un-modpack" aria-label="Permalink to &quot;Importer un modpack&quot;">​</a></h2><ul><li><strong>Double-cliquez</strong> sur un fichier <code>.kpack</code> (version installée de Kodus), ou</li><li>utilisez le bouton <strong>Importer un modpack</strong> en bas de la colonne de gauche, ou</li><li><strong>faites glisser le fichier</strong> sur la fenêtre de Kodus.</li></ul><p>Kodus affiche un aperçu (nom, version, loader, nombre de mods), puis crée l&#39;instance et télécharge l&#39;ensemble des fichiers. Les fichiers <code>.mrpack</code> de Modrinth et les <code>.zip</code> exportés depuis Prism Launcher sont également pris en charge. Les modpacks CurseForge ne le sont pas.</p><h2 id="partager-une-instance" tabindex="-1">Partager une instance <a class="header-anchor" href="#partager-une-instance" aria-label="Permalink to &quot;Partager une instance&quot;">​</a></h2><ol><li>Page de l&#39;instance → bouton <strong>Exporter</strong>.</li><li>Format : <strong>.kpack</strong> pour les utilisateurs de Kodus, <strong>.mrpack</strong> pour les utilisateurs de Modrinth App ou de Prism Launcher.</li><li>Cochez les éléments à inclure. Les mondes (<code>saves</code>) et les captures d&#39;écran sont décochés par défaut : ne cochez <code>saves</code> que pour partager un monde.</li><li>Mode du <code>.kpack</code> : <strong>Modrinth</strong> (fichier léger, les mods sont téléchargés lors de l&#39;import) ou <strong>pack autonome</strong> (tous les fichiers inclus, plus volumineux, utilisable sans Modrinth).</li><li>Partagez le fichier obtenu.</li></ol>',7)])])}const g=a(n,[["render",t]]);export{m as __pageData,g as default};
